style.css:
/* Pure White — All websites */
/* i really want this to be global */

/* kleuren aanpassen kan hier */
:root {
  --my-bg: #ffffff;
  --my-surface: #fafafa;
  --my-text: #252525;
  --my-muted: #888888;
  --my-border: #eeeeee;
  --my-accent: #555555;
}

/* clean backgrounds */
body,
main,
section,
article {
  background-color: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* rustige typografie */
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI",
    Helvetica, Arial, sans-serif !important;
  letter-spacing: -0.2px !important;
}

/* minimalistische links */
a {
  color: var(--my-accent) !important;
  text-decoration: none !important;
  transition: opacity 0.2s ease !important;
}

a:hover {
  opacity: 0.65 !important;
}

/* subtiele randen */
hr,
input,
textarea,
select {
  border-color: var(--my-border) !important;
}

/* rustige invoervelden */
input,
textarea,
select {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border-radius: 8px !important;
}

/* afbeeldingen iets zachter */
img {
  border-radius: 6px;
}

/* subtiele scrollbalk */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: #dddddd !important;
  border-radius: 10px !important;
}

::-webkit-scrollbar-track {
  background: #ffffff !important;
}
